{"path": "csvfix/impl.py", "content": "def parse(line):
    """Split a CSV line into exactly 3 trimmed fields.

    Returns None when the number of columns is not 3.
    """
    fields = [f.strip() for f in line.split(",")]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """Sum the third column (amount) of the rows, skipping blank amounts."""
    total = 0
    for row in rows:
        if len(row) > 2 and row[2]:
            total += int(row[2])
    return total
"}

{"path": "rules/engine.py", "content": "def evaluate(rules, facts):
    """Evaluate a rule against a set of facts.

    A rule is a single-key dict:
      {"all": [keys]} -> True when every key is truthy in facts.
      {"any": [keys]} -> True when at least one key is truthy in facts.
    Unknown rule shapes evaluate to False.
    """
    if "all" in rules:
        return all(facts.get(key, False) for key in rules["all"])
    if "any" in rules:
        return any(facts.get(key, False) for key in rules["any"])
    return False
